// Sums the integers from lo to hi, both included.
export function rangeSum(lo, hi) {
  let total = 0;
  for (let i = lo; i <= hi; i += 1) total += i;
  return total;
}

// Clamps x into [lo, hi].
export function clamp(x, lo, hi) {
  return Math.min(Math.max(x, lo), hi);
}

// The mean of the integers from lo to hi, both included.
export function rangeMean(lo, hi) {
  return rangeSum(lo, hi) / (hi - lo);
}

